            self.send_request("Request: Execute malware scan\n")
            response = self.receive_response()

            if response == "Scan complete":
                continue

            # Process the response and handle potential errors
            print(response)

            if response:
                result, error = self.execute_command(response)
                print(f"Result: {result}, Error: {error}")
                if error:
                    raise Exception(f"Error from malware engine: {error}")

    def close(self):
        self.client_socket.close()


